//
// LAMP1 多发送方仲裁。
//
// 固件不分发送方：Mac 端 LampSender 与手机同时推包时，两路包交替到达，一轮 loop 只留
// 最后一个 —— 画面在两份分析结果之间来回跳，拍点相位、BPM 互相打架，起音标记叠加。
//
// 包尾带一个优先级字节（v3，见 LampSyncPacket.prio），数大者优先：
//   · 不低于当前发送方的包，照收（同级或更高级的接管立即生效）；
//   · 更低的包，只有当前发送方断流超过 freshMs 才收 —— 高的停发（Mac 静音时停发让位）
//     之后，低的自动顶上；高的一恢复发包，马上抢回来。
// 旧包（v1 336B / v2 341B）没有这个字节，按最低级 kSenderLegacy 算。
#include <stdint.h>

namespace lamp {

constexpr uint8_t kSenderLegacy  = 0;   // 不带优先级的旧发送端
constexpr uint8_t kSenderPhone   = 1;   // 手机（Android 推送音频）
constexpr uint8_t kSenderDesktop = 2;   // Mac 端 LampSender、tools/wled_sync_sender.py

struct SenderArbiter {
  uint8_t  prio = 0;
  uint32_t lastMs = 0;
  bool     seen = false;

  // 收到一个优先级为 p 的包：要不要用它。用了就记下它的优先级与时间。
  // 时间差用无符号减法，millis() 回绕也成立。
  bool accept(uint8_t p, uint32_t now, uint32_t freshMs) {
    if (seen && p < prio && (uint32_t)(now - lastMs) < freshMs) return false;
    prio = p;
    lastMs = now;
    seen = true;
    return true;
  }
};

}  // namespace lamp
